            b = bytearray(b'\xff' * 188)
            b[:4] = bytes((71, pid >> 8 & 31 | (64 if start else 0), pid & 255, 16 | self.cc.get(pid, 0)))
            self.cc[pid] = self.cc.get(pid, 0) + 1 & 15
