            adapt = 8 if pcr is not None else 0
            n = min(len(data), capacity)
            if n < capacity:
                adapt = 184 - n
            pos = 4
            if adapt:
                b[3] |= 32
                b[pos] = adapt - 1
                if adapt >= 2:
                    b[pos + 1] = 0
                if pcr is not None:
                    v = pcr & (1 << 33) - 1
                    b[pos + 1:pos + 8] = bytes((16, v >> 25 & 255, v >> 17 & 255, v >> 9 & 255, v >> 1 & 255, v << 7 & 255 | 126, 0))
