class _sg_stream_BoundedBuffer:

    def __init__(self, capacity, timeout):
        if not 188 <= capacity <= 16 << 20 or timeout <= 0:
            raise ValueError('buffer configuration invalid')
        self.capacity = capacity
        self.timeout = timeout
        self.data = bytearray()
        self.condition = _sg_stream_threading.Condition()
        self.eof = False
        self.cancelled = False
        self.error = None
        self.peak_bytes = 0

    def put(self, data):
        view = memoryview(data)
        while view:
            deadline = _sg_stream_time.monotonic() + self.timeout
            with self.condition:
                while len(self.data) >= self.capacity and (not self.cancelled):
                    remaining = deadline - _sg_stream_time.monotonic()
                    if remaining <= 0:
                        raise _sg_stream_GridError('buffer_backpressure_timeout')
                    self.condition.wait(remaining)
                if self.cancelled:
                    raise _sg_stream_Cancelled('reader_closed')
                n = min(len(view), self.capacity - len(self.data))
                self.data.extend(view[:n])
                self.peak_bytes = max(self.peak_bytes, len(self.data))
                view = view[n:]
                self.condition.notify_all()

    def finish(self, error=None):
        with self.condition:
            if self.error is None:
                self.error = error
            self.eof = True
            self.condition.notify_all()

    def wait_ready(self):
        with self.condition:
            self._wait()

    def _wait(self):
        deadline = _sg_stream_time.monotonic() + self.timeout
        while not self.data and (not self.eof) and (not self.cancelled):
            remaining = deadline - _sg_stream_time.monotonic()
            if remaining <= 0:
                raise _sg_stream_StreamError('Grid read timed out')
            self.condition.wait(remaining)
        if not self.data and self.error and (not self.cancelled):
            raise self.error

    def read(self, size):
        if size == 0:
            return b''
        with self.condition:
            self._wait()
            n = min(size if size >= 0 else self.capacity, len(self.data))
            data = bytes(self.data[:n])
            del self.data[:n]
            self.condition.notify_all()
            return data

    def close(self):
        with self.condition:
            self.cancelled = True
            self.data.clear()
            self.condition.notify_all()

def _sg_stream_receive(config, network, emit, report, stats):
    session = credentials = sink = None
    primary = None
    try:
        session = _sg_stream_bootstrap(config, report, http_factory=lambda: _sg_stream_HTTP(network.stop))
        credentials = _sg_stream_obtain_certificate(network, session, report)
        parents, node_key = _sg_stream_discover_parent(network, session.center, credentials, report)
        sink = _sg_stream_MediaSink(emit, config.capture_dir)
        stats.update(sink.stats)
        sink.stats = stats
        _sg_stream_receive_media(network, parents, session.bno, node_key, sink, report, config.duration, config.max_bytes, rediscover=lambda: _sg_stream_discover_parent(network, session.center, credentials, report))
        if not sink.mux.video_frames:
            raise _sg_stream_GridError('no_playable_grid_video')
    except BaseException as error:
        primary = error
        raise
    finally:
        try:
            if sink:
                try:
                    sink.close()
                except Exception:
                    if primary is None:
                        raise
                    report('cleanup_failed_after_primary_error')
        finally:
            if credentials:
                credentials.clear()
            if session:
                session.clear()
            config.clear()
            network.close()

class _sg_stream_SoopGridReader(_sg_stream_StreamIO):

    def __init__(self, stream, runner=_sg_stream_receive):
        super().__init__()
        self.stream = stream
        self.network = _sg_stream_Network()
        self.buffer = _sg_stream_BoundedBuffer(stream.buffer_size, stream.timeout)
        self.runner = runner
        self.thread = None
        self.stats = {}
        self.stages = _sg_stream_deque(maxlen=128)
        self._close_lock = _sg_stream_threading.Lock()
        self._closing = False
        self.failure_code = None
        self.reader_state = 'initializing'
        self.diagnostics = _sg_stream_Diagnostics(stream.config.diagnostics_dir, self._snapshot)

    def _snapshot(self):
        facts = dict(self.stats)
        with self.buffer.condition:
            facts.update(buffer_used_bytes=len(self.buffer.data), buffer_peak_bytes=self.buffer.peak_bytes)
        with self.network._lock:
            facts['active_sockets'] = len(self.network._sockets)
        facts['reader_state'] = self.reader_state
        return facts

    def _report(self, event):
        self.stages.append(event)
        stage = next((x for x in ('bootstrap', 'gateway', 'center', 'parent') if event.startswith(x)), 'receiver')
        self.diagnostics.event(stage, event)

    def open(self):
        if self.thread is not None or self.closed:
            raise _sg_stream_StreamError('Grid reader already opened or closed')
        self.diagnostics.start()
        self.thread = _sg_stream_threading.Thread(target=self._run, name='soop-grid-receiver', daemon=True)
        self.thread.start()
        try:
            self.buffer.wait_ready()
        except Exception as error:
            if not self.failure_code:
                self.diagnostics.fail(_sg_stream_GridError('reader_timeout'))
            self.close()
            if self.failure_code and error is not None:
                error.grid_error_code = self.failure_code
            raise
        return self

    def _run(self):
        error = None
        try:
            self.runner(self.stream.config, self.network, self.buffer.put, self._report, self.stats)
            self.diagnostics.complete(self.stats.get('stop_reason', 'receiver_completed_unknown'))
        except BaseException as exc:
            code = _sg_stream_safe_error(exc)
            self.failure_code = code
            reason = 'center_rediscovery_failed' if self.stats.get('center_rediscovery_failed') and _sg_stream_stop_reason(exc) != 'authentication_denied' else None
            self.diagnostics.fail(exc, reason)
            if not self._closing:
                error = _sg_stream_StreamError('SOOP Grid: ' + code)
                _sg_stream__log.error('Native Grid receiver stopped: %s (%s)', code, self.diagnostics.reason)
        finally:
            self.network.close()
            self.buffer.finish(error)
            self.diagnostics.event(event='worker_finished')
            self.diagnostics.summary()

    def readable(self):
        return not self.closed

    def read(self, size=-1):
        if self.closed or self._closing:
            return b''
        try:
            result = self.buffer.read(size)
            if result:
                self.reader_state = 'streaming'
            elif size != 0:
                self.reader_state = 'eof'
                self.diagnostics.event('reader', 'reader_eof')
            return result
        except _sg_stream_StreamError as exc:
            self.reader_state = 'error'
            if not self.failure_code:
                self.diagnostics.fail(_sg_stream_GridError('reader_timeout'))
            self.diagnostics.event('reader', 'reader_error')
            self.close()
            raise OSError(str(exc)) from None

    def readinto(self, b):
        data = self.read(len(b))
        b[:len(data)] = data
        return len(data)

    def close(self):
        with self._close_lock:
            if self.closed:
                return
            if self.thread and self.thread.is_alive() and (self.diagnostics.reason is None):
                self.diagnostics.complete('user_cancelled')
            self._closing = True
            self.network.close()
            self.buffer.close()
        if self.thread and self.thread is not _sg_stream_threading.current_thread():
            self.thread.join(12)
        self.stream.config.clear()
        self.reader_state = 'closed'
        self.diagnostics.event('reader', 'reader_closed')
        self.diagnostics.close()
        super().close()

class _sg_stream_SoopGridStream(_sg_stream_Stream):
    __shortname__ = 'grid'

    def __init__(self, session, config):
        super().__init__(session)
        self.config = config
        self.buffer_size = min(max(int(session.get_option('ringbuffer-size') or 8 << 20), 188), 16 << 20)
        self.timeout = float(session.get_option('stream-timeout') or 60)
        self._opened = False

    def open(self):
        if self._opened:
            raise _sg_stream_StreamError('Grid streams are single-session; enumerate again to reopen')
        self._opened = True
        try:
            return _sg_stream_SoopGridReader(self).open()
        except _sg_stream_GridError as exc:
            raise _sg_stream_StreamError('SOOP Grid: ' + _sg_stream_safe_error(exc)) from None

class _sg_stream_OfficialHLSFallback:
    """Lazy, one-shot delegation to Streamlink's maintained SOOP plugin."""

    def __init__(self, session, url, account, password, stream_password):
        self.session, self.url, self.account = (session, url, account)
        self.password, self.stream_password = (password, stream_password)
        self.used = False

    def __repr__(self):
        return '<OfficialHLSFallback credentials=redacted>'

    def clear(self):
        self.password = self.stream_password = self.account = ''

    def open(self):
        if self.used:
            raise _sg_stream_StreamError('Official SOOP HLS fallback is single-use')
        self.used = True
        try:
            self.session.plugins.load_builtin()
            plugin_class = self.session.plugins.get_loaded().get('soop')
            if plugin_class is None:
                raise _sg_stream_StreamError('Streamlink built-in SOOP plugin is unavailable')
            plugin = plugin_class(self.session, self.url, options={'username': self.account, 'password': self.password, 'stream-password': self.stream_password})
            streams = plugin.streams()
            selected = streams.get('original') or next(iter(streams.values()), None)
            if selected is None:
                raise _sg_stream_StreamError('Official SOOP HLS plugin returned no playable stream')
            return selected.open()
        finally:
            self.clear()

class _sg_stream_SoopAutoStream(_sg_stream_Stream):
    """Grid-first stream; only pre-output transport failures can select HLS."""
    __shortname__ = 'auto'

    def __init__(self, session, grid, fallback):
        super().__init__(session)
        self.grid = grid
        self.fallback = fallback
        self._opened = False

    def open(self):
        if self._opened:
            raise _sg_stream_StreamError('SOOP auto streams are single-session; enumerate again to reopen')
        self._opened = True
        try:
            reader = self.grid.open()
            if self.fallback:
                self.fallback.clear()
            return reader
        except _sg_stream_StreamError as exc:
            if getattr(exc, 'grid_error_code', None) not in _sg_stream__INITIAL_TRANSPORT_FAILURES:
                if self.fallback:
                    self.fallback.clear()
                raise
            if self.fallback is None:
                raise
            _sg_stream__log.warning('Native Grid unavailable before media output; starting the official SOOP HLS stream')
            try:
                return self.fallback.open()
            finally:
                self.fallback.clear()


